import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { randomBytes, randomUUID } from 'node:crypto'
import { once } from 'node:events'
import { mkdtempSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { createServer } from 'node:net'
import { tmpdir } from 'node:os'
import { basename, dirname, join, resolve } from 'node:path'

// Only accepts the isolated all-module configuration generated by production-smoke.
// Never accepts the operator's deployment configuration or an existing restore target.
const sourceFile = resolve(process.argv[2] || '')
const source = JSON.parse(readFileSync(sourceFile, 'utf8'))
assert.match(source.name, /^dco-smoke-[a-f0-9]{12}$/)
assert.match(basename(dirname(sourceFile)), /^dco-production-smoke-/)
const base = source.services['core-service'].environment.DCO_PUBLIC_BASE_URL
assert.match(base, /^http:\/\/127\.0\.0\.1:\d+$/)
const modules = { core: ['core-service', 'core_data'], time: ['time-tracking', 'time_tracking_data'], inventory: ['inventory-management', 'inventory_management_data'], agile: ['agile-project-management', 'agile_project_data'] }
for (const [service, volume] of Object.values(modules)) {
  assert.ok(source.services[service], 'Recovery smoke requires all three products')
  assert.equal(source.volumes[volume].name, `${source.name}_${volume}`)
  assert.ok(source.services[service].volumes.some((mount) => mount.type === 'volume' && mount.source === volume && mount.target === '/data'))
}
assert.ok(source.services.backup, 'The generated isolated backup profile is required')
const backupDirectory = source.services.backup.volumes.find((mount) => mount.target === '/backups').source
assert.equal(resolve(backupDirectory), join(dirname(sourceFile), 'backups'))
const prefix = process.env.DOCKER_CONTEXT ? ['--context', process.env.DOCKER_CONTEXT] : []
const sourceCompose = [...prefix, 'compose', '-p', source.name, '-f', sourceFile, '--profile', 'backup']
async function docker(args, tolerateFailure = false) {
  const child = spawn('docker', args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] })
  let output = ''
  child.stdout.on('data', (chunk) => { output += chunk })
  child.stderr.on('data', (chunk) => { output += chunk })
  const [code] = await once(child, 'exit')
  if (code && !tolerateFailure) throw new Error(`Docker recovery command failed (${code}): ${output}`)
  return { code, output }
}
async function http(origin, path, cookie, body) {
  const response = await fetch(origin + path, { redirect: 'manual', signal: AbortSignal.timeout(10_000), method: body ? 'POST' : 'GET', headers: { Origin: origin, ...(cookie ? { Cookie: cookie } : {}), ...(body ? { 'Content-Type': 'application/json' } : {}) }, body: body ? JSON.stringify(body) : undefined })
  assert.ok(response.ok, `${path}: ${response.status} ${await response.clone().text()}`)
  return response
}
async function login(origin) {
  const response = await http(origin, '/api/core/auth/login', '', { email: 'launch-admin@example.invalid', password: 'Changed!SmokePassword2026' })
  const cookie = response.headers.getSetCookie().find((value) => value.startsWith('dco_core_session='))?.split(';')[0]
  assert.ok(cookie)
  return cookie
}
async function capture(origin, cookie) {
  const data = await Promise.all(['/api/core/users', '/time/api/state', '/inventory/api/inventorySystem/state', '/agile/api/agile/workspace'].map(async (path) => (await http(origin, path, cookie)).json()))
  return {
    users: data[0].users.map(({ id, name, email, role, active, memberships }) => ({ id, name, email, role, active, memberships })),
    time: { entries: data[1].timeEntries, requests: data[1].requests, absences: data[1].absences },
    inventory: { items: data[2].items, records: data[2].records, receiptLines: data[2].receiptLines, recordEvents: data[2].recordEvents },
    agile: { state: data[3].state, revision: data[3].revision },
  }
}

const recoveryFolder = mkdtempSync(join(tmpdir(), 'dco-recovery-smoke-'))
const restoreProject = `dco-restore-test-${randomBytes(6).toString('hex')}`
const restoreFile = join(recoveryFolder, 'compose.json')
const restoreCompose = [...prefix, 'compose', '-p', restoreProject, '-f', restoreFile]
let restoreDefined = false
const createdVolumes = []
try {
  const cookie = await login(base)
  const workspace = await (await http(base, '/agile/api/agile/workspace', cookie)).json()
  const id = `recovery-${randomUUID()}`
  await http(base, '/time/api/clock', cookie, { action: 'start_work' })
  await http(base, '/time/api/clock', cookie, { action: 'stop_work' })
  await http(base, '/inventory/api/inventorySystem/items', cookie, { name: 'Recovery verification item', sku: id })
  await http(base, '/agile/api/agile/workspace/commands', cookie, { requestId: randomUUID(), revision: workspace.revision, operation: { type: 'create_item', item: { id, title: 'Verified disaster recovery record', type: 'Task', area: 'Project', status: 'Ready', owner: 'Project Management', stakeholder: '', priority: 'High', effort: 1, businessValue: 5, risk: 1, sprint: 'Sprint 1', release: '', due: '2026-09-06', dependsOn: '', acceptance: 'Survive encrypted backup, restore, and application restart.', updatedAt: new Date().toISOString() } } })
  await docker([...sourceCompose, 'exec', '-T', 'inventory-management', 'node', '-e', 'const fs=require("node:fs"); fs.mkdirSync("/data/media/recovery-drill/nested",{recursive:true,mode:0o700}); fs.writeFileSync("/data/media/recovery-drill/nested/receipt.txt","Synthetic receipt preserved byte-for-byte.\\n",{mode:0o600});'])
  const before = await capture(base, cookie)
  assert.ok(before.time.entries.length > 0)
  assert.ok(before.inventory.items.some((item) => item.sku.toLowerCase() === id))
  await docker([...sourceCompose, 'up', '-d', '--no-build', 'backup'])
  let healthy = false
  for (let attempt = 0; attempt < 120; attempt++) {
    if ((await docker([...sourceCompose, 'exec', '-T', 'backup', 'node', '/app/deploy-scripts/scheduled-backup.mjs', '--health'], true)).code === 0) { healthy = true; break }
    await new Promise((done) => setTimeout(done, 500))
  }
  assert.ok(healthy, 'The real Compose scheduler must publish a healthy completed backup')
  await docker([...sourceCompose, 'stop', 'backup'])
  const bundle = readdirSync(backupDirectory).filter((name) => name.endsWith('.dco-backup')).sort().at(-1)
  assert.ok(bundle)
  await docker([...sourceCompose, 'run', '--rm', '--no-deps', '--entrypoint', 'node', '-v', `${recoveryFolder}:/restore`, 'backup', '/app/deploy-scripts/restore-suite.mjs', `--bundle=/backups/${bundle}`, '--target=/restore/verified', '--key-file=/run/secrets/backup_key'])
  // Restored files remain root-private on a Linux host. Inspect through the
  // trusted helper instead of weakening permissions for the host test runner.
  const receipt = await docker([...prefix, 'run', '--rm', '--user', '0:0', '--entrypoint', 'node', '--mount', `type=bind,src=${join(recoveryFolder, 'verified')},dst=/source,readonly`, source.services['core-service'].image, '-e', 'process.stdout.write(JSON.stringify(require("node:fs").readFileSync("/source/inventory/media/recovery-drill/nested/receipt.txt","utf8")));'])
  assert.equal(JSON.parse(receipt.output), 'Synthetic receipt preserved byte-for-byte.\n')

  const probe = createServer().listen(0, '127.0.0.1')
  await once(probe, 'listening')
  const port = probe.address().port
  await new Promise((done) => probe.close(done))
  const restoredBase = `http://127.0.0.1:${port}`
  const restored = structuredClone(source)
  restored.name = restoreProject
  delete restored.services.backup
  for (const [key, volume] of Object.entries(restored.volumes)) volume.name = `${restoreProject}_${key}`
  for (const [key, network] of Object.entries(restored.networks || {})) network.name = `${restoreProject}_${key}`
  for (const service of Object.values(restored.services)) {
    delete service.build
    if (service.environment?.DCO_PUBLIC_BASE_URL) service.environment.DCO_PUBLIC_BASE_URL = restoredBase
    if (service.environment?.DCO_CORE_LOGIN_URL) service.environment.DCO_CORE_LOGIN_URL = restoredBase
    if (service.environment?.CORS_ORIGIN) service.environment.CORS_ORIGIN = restoredBase
    if (service.environment?.APP_BASE_URL) service.environment.APP_BASE_URL = `${restoredBase}/time`
  }
  for (const key of ['DCO_INITIAL_ADMIN_NAME', 'DCO_INITIAL_ADMIN_EMAIL', 'DCO_INITIAL_ADMIN_PASSWORD']) restored.services['core-service'].environment[key] = ''
  restored.services.caddy.environment.DCO_APP_HOST = restoredBase
  restored.services.caddy.ports = [{ target: port, published: String(port), host_ip: '127.0.0.1', protocol: 'tcp' }]
  writeFileSync(restoreFile, JSON.stringify(restored, null, 2), { mode: 0o600 })
  restoreDefined = true
  for (const [module, [, key]] of Object.entries(modules)) {
    const volume = restored.volumes[key].name
    assert.ok(volume.startsWith(`${restoreProject}_`))
    assert.notEqual((await docker([...prefix, 'volume', 'inspect', volume], true)).code, 0, 'Recovery volumes must not already exist')
    await docker([...prefix, 'volume', 'create', volume])
    createdVolumes.push(volume)
    await docker([...prefix, 'run', '--rm', '--user', '0:0', '--entrypoint', 'node', '--mount', `type=bind,src=${join(recoveryFolder, 'verified', module)},dst=/source,readonly`, '--mount', `type=volume,src=${volume},dst=/destination`, restored.services['core-service'].image, '-e', 'const fs=require("node:fs"); if(fs.readdirSync("/destination").length) throw new Error("Destination must be empty"); fs.cpSync("/source","/destination",{recursive:true,force:false,errorOnExist:true}); require("node:child_process").execFileSync("chown",["-R","1000:1000","/destination"]);'])
  }
  await docker([...restoreCompose, 'up', '-d', '--no-build'])
  for (const path of ['/api/health', '/time/api/health', '/inventory/api/health', '/agile/api/health']) {
    let ready = false
    for (let attempt = 0; attempt < 120; attempt++) {
      if (await fetch(restoredBase + path).then((response) => response.ok).catch(() => false)) { ready = true; break }
      await new Promise((done) => setTimeout(done, 500))
    }
    assert.ok(ready, `Restored ${path} must start without bootstrap users`)
  }
  const after = await capture(restoredBase, await login(restoredBase))
  assert.deepEqual(after, before, 'Core identities, encrypted Time records, Inventory data, and shared Agile work must survive recovery')
  assert.ok(after.agile.state.items.some((item) => item.id === id))
  const result = { ok: true, sourceProject: source.name, restoreProject, modules: Object.keys(modules), nestedAttachment: true, scheduler: true, restoredLogin: true, applicationDataEqual: true }
  writeFileSync(join(dirname(sourceFile), 'recovery-result.json'), JSON.stringify(result, null, 2))
  console.log(`Production backup/recovery passed: ${JSON.stringify(result)}`)
} finally {
  await docker([...sourceCompose, 'stop', 'backup'], true)
  if (restoreDefined) {
    assert.match(restoreProject, /^dco-restore-test-[a-f0-9]{12}$/)
    await docker([...restoreCompose, 'down', '--volumes', '--remove-orphans'])
  }
  // Older Compose versions leave volumes created explicitly outside Compose.
  for (const volume of createdVolumes) {
    assert.ok(volume.startsWith(`${restoreProject}_`))
    if ((await docker([...prefix, 'volume', 'inspect', volume], true)).code === 0) await docker([...prefix, 'volume', 'rm', volume])
  }
}
